use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn rotate_left_spec(list: Seq<i32>, n: nat) -> Seq<i32>
    requires
        0 < n < list.len(),
    ensures
        |result| == |list|,
    decreases list.len(),
{
    if list.len() == 0 {
        seq![]
    } else {
        // Concatenate list[n..] with list[0..n]
        list.subrange(n as int, list.len() as int) + list.subrange(0, n as int)
    }
}

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        0 < n < list.len(),
    ensures
        new_list@ == rotate_left_spec(list@, n as nat),
{
    let length = list.len();
    
    // Create a new vector with the same capacity
    let mut new_list = Vec::new();
    
    // First, append elements from n to end
    let mut i = n;
    while i < length
        invariant
            n <= i <= length,
            new_list@ == list@.subrange(n as int, i as int),
        decreases length - i,
    {
        new_list.push(list[i]);
        i = i + 1;
    }
    
    // Then, append elements from 0 to n
    let mut j = 0;
    while j < n
        invariant
            0 <= j <= n,
            new_list@ == list@.subrange(n as int, length as int) + 
                        list@.subrange(0, j as int),
        decreases n - j,
    {
        new_list.push(list[j]);
        j = j + 1;
    }
    
    new_list
}

} // verus!

